before.css:
#hrv-classroom-explorations-root.hrv-hub-doorway {
  width: 100%;
  min-height: 420px;
}

#hrv-classroom-explorations-root .hrv-hub-outage[hidden] {
  display: none !important;
}

#hrv-classroom-explorations-root .hrv-hub-outage {
  display: grid;
  width: min(680px, calc(100% - 28px));
  min-height: 410px;
  margin: 42px auto;
  padding: clamp(26px, 5vw, 48px);
  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(109, 157, 211, 0.28);
  border-radius: 30px;
  color: #eef6ff;
  background:
    radial-gradient(circle at 18% 12%, rgba(86, 222, 191, 0.2), transparent 304px),
    radial-gradient(circle at 82% 6%, rgba(131, 151, 255, 0.2), transparent 288px),
    linear-gradient(145deg, #0d2853, #07172f);
  box-shadow: 0 24px 60px rgba(8, 24, 53, 0.28);
  font-family: "Atkinson Hyperlegible", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  text-align: center;
}

#hrv-classroom-explorations-root .hrv-hub-outage__scene {
  position: relative;
  display: grid;
  width: min(240px, 68vw);
  aspect-ratio: 1;
  margin: -12px auto -8px;
  place-items: center;
}

#hrv-classroom-explorations-root .hrv-hub-outage__scene::before {
  content: "";
  position: absolute;
  inset: 8%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 242, 168, 0.42), rgba(114, 216, 192, 0.13) 44%, transparent 72%);
  filter: blur(4px);
}

#hrv-classroom-explorations-root .hrv-hub-outage__guide-fallback,
#hrv-classroom-explorations-root .hrv-hub-outage__guide {
  position: absolute;
  z-index: 2;
  width: 78%;
  height: 78%;
}

#hrv-classroom-explorations-root .hrv-hub-outage__guide-fallback {
  display: grid;
  place-items: center;
  font-size: clamp(80px, 18vw, 120px);
  filter: drop-shadow(0 18px 24px rgba(0, 0, 0, 0.2));
}

#hrv-classroom-explorations-root .hrv-hub-outage__guide {
  object-fit: contain;
  opacity: 0;
  filter: drop-shadow(0 18px 24px rgba(0, 0, 0, 0.24));
  transition: opacity 180ms ease;
}

#hrv-classroom-explorations-root.hrv-guide-ready .hrv-hub-outage__guide {
  opacity: 1;
}

#hrv-classroom-explorations-root.hrv-guide-ready .hrv-hub-outage__guide-fallback {
  opacity: 0;
}

#hrv-classroom-explorations-root .hrv-hub-outage__question,
#hrv-classroom-explorations-root .hrv-hub-outage__map {
  position: absolute;
  z-index: 3;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.38);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.22);
}

#hrv-classroom-explorations-root .hrv-hub-outage__question {
  top: 7%;
  right: 5%;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  color: #243557;
  background: #f8e786;
  font: 900 25.6px/1 "Nunito Sans", system-ui, sans-serif;
  transform-origin: 50% 50%;
  animation: hrv-hub-guide-question 2.4s ease-in-out infinite;
}

#hrv-classroom-explorations-root .hrv-hub-outage__map {
  right: 4%;
  bottom: 16%;
  width: 45px;
  height: 38px;
  border-radius: 12px;
  background: rgba(11, 33, 70, 0.9);
  font-size: 23.2px;
  transform: rotate(8deg);
}

#hrv-classroom-explorations-root .hrv-hub-outage__eyebrow {
  margin: 0 0 8px;
  color: #79e4cb;
  font-size: 12.5px;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

#hrv-classroom-explorations-root .hrv-hub-outage__title {
  margin: 0;
  color: #fff;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(28.8px, 5vw, 44.8px);
  line-height: 1.08;
}

#hrv-classroom-explorations-root .hrv-hub-outage__copy {
  max-width: 520px;
  margin: 14px 0 0;
  color: #cadcf5;
  font-size: 16px;
  line-height: 1.65;
}

@keyframes hrv-hub-guide-question {
  0%, 100% { transform: rotate(-5deg) translateY(0); }
  50% { transform: rotate(7deg) translateY(-5px); }
}

@media (prefers-reduced-motion: reduce) {
  #hrv-classroom-explorations-root .hrv-hub-outage__question {
    animation: none;
  }
}

